import { Axis as VisxAxis, TickLabelProps } from '@visx/axis';
import { TextProps } from '@visx/text';
import React from 'react';
import styled from 'styled-components';

import { AXIS_TICK_LENGTH, axisFontProps } from './constants.js';
import { AxisProps } from './types.js';
import { centerEllipsizeText } from '../../../../typography/utils.js';
import { useComputedFontStyle } from '../../hooks/useComputedFontStyle.js';
import { TickPrimitiveValue } from '../../types/tick-value.js';

const StyledSVG = /* @__PURE__ */ styled.svg`
  display: block;
  /* This is needed to avoid long characters being cut off*/
  overflow: visible;
`;

const labelProps: TextProps = { ...axisFontProps, textAnchor: 'middle' };

/**
 * @internal
 */
export const Axis = ({
  width = '100%',
  height = '100%',
  containerSize,
  label,
  tickLabelProps = (...args) => ({}),
  ...restProps
}: AxisProps) => {
  const defaultTickLabelProps: TickLabelProps<TickPrimitiveValue> = (
    ...args
  ) => ({
    ...axisFontProps,
    ...(typeof tickLabelProps === 'function'
      ? tickLabelProps(...args)
      : tickLabelProps),
  });

  const fontStyle = useComputedFontStyle(axisFontProps);

  const truncatedLabel = label
    ? centerEllipsizeText(label, fontStyle, containerSize)
    : '';
  const testId = (restProps as unknown as Record<string, string>)[
    'data-testid'
  ];

  return (
    <StyledSVG width={width} height={height} data-testid={testId}>
      <VisxAxis
        label={truncatedLabel}
        labelProps={labelProps}
        tickLabelProps={defaultTickLabelProps}
        tickLength={AXIS_TICK_LENGTH}
        hideTicks
        hideAxisLine
        {...restProps}
      />
    </StyledSVG>
  );
};
Axis['displayName'] = 'Axis';
